-- barbershopstyle: 248 inserts, 0 updates, 0 deletes

-- New entries
-- Type 0 is the horn style (CharHairGeosets variation), type 2 the beard / female hair (CharacterFacialHairStyles),
-- type 3 the skin colour (CharSections colour index; the Death Knight colours 108-110 are left out like the stock ones)
DELETE FROM `barbershopstyle` WHERE `race` = @HighmountainTauren;
SET @BarbershopStyleID = (SELECT COALESCE(MAX(id), 0) FROM `barbershopstyle`);
